patches.good:
diff --git a/src/tools.ts b/src/tools.ts
index a759807..e804dad 100644
--- a/src/tools.ts
+++ b/src/tools.ts
@@ -1,6 +1,12 @@
+function asRecord(value: unknown): Record<string, unknown> | null {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    return null;
+  }
+  return value as Record<string, unknown>;
+}
+
 export function isToolFailureKind(kind: unknown): boolean {
-  void kind;
-  throw new Error("not implemented");
+  return kind === "agent.tool_call.failed";
 }

 export function toolFailureSummary(events: unknown): {
@@ -8,11 +14,33 @@ export function toolFailureSummary(events: unknown): {
   failures: number;
   failure_ts: string[];
 } {
-  void events;
-  throw new Error("not implemented");
+  const out = { attempts: 0, failures: 0, failure_ts: [] as string[] };
+  if (!Array.isArray(events)) {
+    return out;
+  }
+  for (const event of events) {
+    const rec = asRecord(event);
+    if (rec === null || typeof rec.kind !== "string") {
+      continue;
+    }
+    if (rec.kind === "agent.tool_call") {
+      out.attempts += 1;
+    }
+    if (rec.kind === "agent.tool_call.failed") {
+      out.failures += 1;
+      if (typeof rec.ts === "string") {
+        out.failure_ts.push(rec.ts);
+      }
+    }
+  }
+  return out;
 }

 export function toolFailureRate(events: unknown): number | null {
-  void events;
-  throw new Error("not implemented");
+  const summary = toolFailureSummary(events);
+  const total = summary.attempts + summary.failures;
+  if (total === 0) {
+    return null;
+  }
+  return summary.failures / total;
 }

